-- 3.3.3 Vincular Mutuamente Relaciones de Comparación: transformación de funciones a
-- través de la relación mutua (Luciano et al., 2009). Una función con umbral («justo»)
-- en un miembro y la pregunta por el otro, para que la respuesta se deduzca con
-- seguridad: A → B (situación del polo de la frase) y B → A (situación contraria).
begin;
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Pim es más alto que Tok. ¿Quién es más bajo?", "entrenamiento:B→A": "Pim es más alto que Tok. ¿Quién es más alto?", "transformacion_funciones:A→B": "Pim es más alto que Tok. Pim llega justo a la estantería de arriba. ¿Quién no llega?", "transformacion_funciones:B→A": "Pim es más alto que Tok. Tok cabe justo por debajo de la rama. ¿Quién no cabe?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones de Comparación' and c.nombre = 'Clase 1';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:A→B', $j$Pim es más alto que Tok. Pim llega justo a la estantería de arriba. ¿Quién no llega?$j$, 'transformacion_funciones:B→A', $j$Pim es más alto que Tok. Tok cabe justo por debajo de la rama. ¿Quién no cabe?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones de Comparación' and c.nombre = 'Clase 1';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Comparado con el tren Tasi, el tren Bori es más largo. ¿Qué tren es más corto?", "entrenamiento:B→A": "Comparado con el tren Tasi, el tren Bori es más largo. ¿Qué tren es más largo?", "transformacion_funciones:A→B": "Comparado con el tren Tasi, el tren Bori es más largo. En el tren Bori caben justo todos los niños. ¿En qué tren no caben?", "transformacion_funciones:B→A": "Comparado con el tren Tasi, el tren Bori es más largo. El tren Tasi cabe justo en la estación pequeña. ¿Qué tren no cabe?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones de Comparación' and c.nombre = 'Clase 2';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:A→B', $j$Comparado con el tren Tasi, el tren Bori es más largo. En el tren Bori caben justo todos los niños. ¿En qué tren no caben?$j$, 'transformacion_funciones:B→A', $j$Comparado con el tren Tasi, el tren Bori es más largo. El tren Tasi cabe justo en la estación pequeña. ¿Qué tren no cabe?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones de Comparación' and c.nombre = 'Clase 2';
